insert into public.item_options select * from jsonb_populate_recordset(null::public.item_options,'[{"id": "7df3bdbe-730b-56d4-baa8-c1dc90fca223", "item_id": "0d5b07ed-82ac-542b-b066-9ce3a338dc27", "content_en": null, "content_hy": "Որովհետև գազի մոլեկուլները հեղուկի մոլեկուլներից միշտ ավելի մեծ են։", "option_key": "A", "display_order": 1}, {"id": "d0c5987a-cb92-517b-8438-7fbb0fb0eec3", "item_id": "0d5b07ed-82ac-542b-b066-9ce3a338dc27", "content_en": null, "content_hy": "Որովհետև հեղուկներում մոլեկուլների միջև ընդհանրապես տարածություններ չկան։", "option_key": "B", "display_order": 2}, {"id": "fc67724c-23db-5124-bb35-22e407bc71f2", "item_id": "0d5b07ed-82ac-542b-b066-9ce3a338dc27", "content_en": null, "content_hy": "Որովհետև գազերում մոլեկուլների միջև հեռավորություններն ավելի մեծ են, և փոխադարձ ներթափանցումն ավելի արագ է։", "option_key": "C", "display_order": 3}, {"id": "02b5b9a7-adaa-5979-be12-7a094b787f25", "item_id": "0d5b07ed-82ac-542b-b066-9ce3a338dc27", "content_en": null, "content_hy": "Որովհետև գազերում դիֆուզիան առաջանում է միայն ծանրության ուժի ազդեցությամբ։", "option_key": "D", "display_order": 4}, {"id": "a290de9a-44f7-576e-b4bd-f780df6caf1b", "item_id": "5249f097-5e24-5e7c-8a0f-d024f934eb86", "content_en": null, "content_hy": "Գազերում, ապա հեղուկներում, ապա պինդ մարմիններում։", "option_key": "A", "display_order": 1}, {"id": "d0a6f1e5-460e-50b1-9148-3f7c14a9e9f6", "item_id": "5249f097-5e24-5e7c-8a0f-d024f934eb86", "content_en": null, "content_hy": "Պինդ մարմիններում, ապա հեղուկներում, ապա գազերում։", "option_key": "B", "display_order": 2}, {"id": "11878b56-6451-55ae-a69a-aeb955825941", "item_id": "5249f097-5e24-5e7c-8a0f-d024f934eb86", "content_en": null, "content_hy": "Հեղուկներում, ապա գազերում, ապա պինդ մարմիններում։", "option_key": "C", "display_order": 3}, {"id": "ed88b338-b801-5f59-819a-56d83dd307ab", "item_id": "5249f097-5e24-5e7c-8a0f-d024f934eb86", "content_en": null, "content_hy": "Բոլոր երեք վիճակներում դիֆուզիան նույն արագությամբ է ընթանում։", "option_key": "D", "display_order": 4}, {"id": "85d3885d-6cf6-5c62-97f7-b13044c1370f", "item_id": "3aeb8644-8afc-5bd7-a77f-8885aaf66649", "content_en": null, "content_hy": "Դիֆուզիայի արագությունը որոշվում է միայն նյութի գույնով։", "option_key": "A", "display_order": 1}, {"id": "bd86309e-96bf-5e00-8f84-fa998728e240", "item_id": "3aeb8644-8afc-5bd7-a77f-8885aaf66649", "content_en": null, "content_hy": "Դիֆուզիան գազերում ամենաարագն է, հեղուկներում՝ ավելի դանդաղ, իսկ պինդ մարմիններում՝ ամենադանդաղը։", "option_key": "B", "display_order": 2}, {"id": "06ae21b4-cae5-597a-9812-128a1c823a93", "item_id": "3aeb8644-8afc-5bd7-a77f-8885aaf66649", "content_en": null, "content_hy": "Դիֆուզիան պինդ մարմիններում ավելի արագ է, քան գազերում և հեղուկներում։", "option_key": "C", "display_order": 3}, {"id": "ff170c59-64ec-5b42-9b3a-170cb16ff6d8", "item_id": "3aeb8644-8afc-5bd7-a77f-8885aaf66649", "content_en": null, "content_hy": "Դիֆուզիան տեղի է ունենում միայն այն դեպքում, երբ նյութերը արտաքին ուժով խառնում են։", "option_key": "D", "display_order": 4}]'::jsonb);
