videncePurposeRationaleHy": "Պահանջում է դասագրքային երեք դիտարկումներից եզրակացնել դիֆուզիայի արագությունների հարաբերական կարգը։"}, "status": "draft", "skill_id": "aaaefcf9-555e-57d3-bb72-9ad6e998e3d0", "stimulus": {}, "item_type": "single_choice", "prompt_en": null, "prompt_hy": "Սենյակում օծանելիքի հոտը տարածվում է կարճ ժամանակում, պղնձարջասպի լուծույթն ու ջուրը միախառնվում են օրերի ընթացքում, իսկ կապարի և ոսկու թիթեղները 20 °C-ում 5 տարում փոխադարձաբար ներթափանցում են ընդամենը 1 մմ։ Ո՞ր եզրակացությունն է համապատասխանում այս դիտարկումներին։", "created_at": "2026-10-02T07:29:09.081662+00:00", "difficulty": 2, "retired_at": null, "updated_at": "2026-10-02T07:29:09.081662+00:00", "version_no": 1, "item_family": "diffusion_rate_comparison_across_states", "variant_key": "diffusion_rate_comparison:02", "variant_seed": null, "review_status": "needs_review", "retired_reason": null, "difficulty_band": "core", "item_template_id": "c89e408d-bdd0-503a-843d-a8291b451c7a", "last_reviewed_at": null, "last_reviewed_by": null, "source_reference": "Գործող Ֆիզիկա 7 ծրագիր՝ Թեմա 2, լրացուցիչ վերջնարդյունք 2(1); Ֆիզիկա 7 (2023), Գլուխ II, §10, տպագիր էջեր 30-32, նկարներ 30-32", "validation_state": "provisional_no_sme_review", "variant_parameters": {"focusKey": "observational_application", "authoredCatalog": true, "evidencePurpose": "application"}, "replacement_item_id": null, "variant_fingerprint": "c23c8a93b75c412e276595c2f6c35ab4"}, "options": [{"id": "85d3885d-6cf6-5c62-97f7-b13044c1370f", "item_id": "3aeb8644-8afc-5bd7-a77f-8885aaf66649", "content_en": null, "content_hy": "Դիֆուզիայի արագությունը որոշվում է միայն նյութի գույնով։", "option_key": "A", "display_order": 1}, {"id": "bd86309e-96bf-5e00-8f84-fa998728e240", "item_id": "3aeb8644-8afc-5bd7-a77f-8885aaf66649", "content_en": null, "content_hy": "Դիֆուզիան գազերում ամենաարագն է, հեղուկներում՝ ավելի դանդաղ, իսկ պինդ մարմիններում՝ ամենադանդաղը։", "option_key": "B", "display_order": 2}, {"id": "06ae21b4-cae5-597a-9812-128a1c823a93", "item_id": "3aeb8644-8afc-5bd7-a77f-8885aaf66649", "content_en": null, "content_hy": "Դիֆուզիան պինդ մարմիններում ավելի արագ է, քան գազերում և հեղուկներում։", "option_key": "C", "display_order": 3}, {"id": "ff170c59-64ec-5b42-9b3a-170cb16ff6d8", "item_id": "3aeb8644-8afc-5bd7-a77f-8885aaf66649", "content_en": null, "content_hy": "Դիֆուզիան տեղի է ունենում միայն այն դեպքում, երբ նյութերը արտաքին ուժով խառնում են։", "option_key": "D", "display_order": 4}], "answerKey": {"answer": "B", "item_id": "3aeb8644-8afc-5bd7-a77f-8885aaf66649", "tolerance": null, "updated_at": "2026-10-02T07:29:09.081662+00:00", "feedback_code": "diffusion_rate_comparison", "accepted_units": [], "canonical_unit": null}, "misconceptions": [{"code": "diffusion_rate_explained_by_unrelated_factor", "mappingNote": "Ժամանակային տարբերությունը սխալմամբ կապվում է նյութի գույնի հետ։", "responseKey": "A"}, {"code": "diffusion_rate_fastest_in_solids", "mappingNote": "Կապար–ոսկի փորձի շատ դանդաղ ընթացքը մեկնաբանվում է հակառակ ուղղությամբ։", "responseKey": "C"}, {"code": "diffusion_rate_requires_external_mixing", "mappingNote": "Դիտված ինքնաբերական խառնումը սխալմամբ պայմանավորվում է արտաքին ուժով։", "responseKey": "D"}]}, "created_at": "2026-10-02T07:29:09.081662+00:00", "created_by": null, "version_no": 1, "change_summary": "15B.8 հեռանկարային ապացուցողական սխեմայով վեցերորդ կառավարվող սևագիր ընտանիքի ստեղծում"}]'::jsonb);
