insert into public.item_template_remediation_guides select * from jsonb_populate_recordset(null::public.item_template_remediation_guides,'[{"id": "7468399d-462e-56e3-871e-cbf6762f39b8", "status": "published", "metadata": {"sprint": "15B.8", "learnerVisible": false, "referenceMetadata": {"textbookSha256": "d8404d572f145d4afe924d0b8af900b3d9ed085a37893594667ab07a2ec12904", "textbookLocator": "Ֆիզիկա 7 (2023), Գլուխ II, §10, տպագիր էջեր 30-32, նկարներ 30-32", "programmeOutcomeLocator": "7-րդ դասարան / Թեմա 2 / Վերջնարդյունքներ / Լրացուցիչ 2(1)"}, "authoringProfileVersion": "haiedu-evidence-blueprint-v1"}, "title_hy": "Ինչպե՞ս համեմատել դիֆուզիայի արագությունը նյութի տարբեր վիճակներում", "hint_1_hy": "Սկսիր այս համեմատությունից՝ գազեր → հեղուկներ → պինդ մարմիններ՝ ամենաարագից ամենադանդաղը։", "hint_2_hy": "Շատ դանդաղ ընթացքը մի՛ նույնացրու բացակայության հետ. կապարն ու ոսկին 20 °C-ում 5 տարում փոխադարձաբար ներթափանցել են 1 մմ։", "created_at": "2026-10-02T07:29:09.081662+00:00", "updated_at": "2026-10-05T09:35:16.143265+00:00", "strategy_hy": "Նույն ջերմաստիճանում համեմատելիս հիշիր ընդհանուր հաջորդականությունը՝ գազերում դիֆուզիան ամենաարագն է, հեղուկներում՝ ավելի դանդաղ, իսկ պինդ մարմիններում՝ ամենադանդաղը։ Պինդ մարմիններում դիֆուզիան չի բացակայում. այն պարզապես շատ դանդաղ է ընթանում։ Դասագրքում գազերի և հեղուկների տարբերությունը կապվում է գազերում մոլեկուլների միջև ավելի մեծ հեռավորությունների և ավելի արագ փոխադարձ ներթափանցման հետ։", "guide_version": 2, "item_template_id": "c89e408d-bdd0-503a-843d-a8291b451c7a", "worked_example_hy": "Օրինակ՝ օծանելիքի հոտը գազային միջավայրում արագ տարածվում է, հեղուկների ինքնաբերական միախառնումը պահանջում է օրեր, իսկ կապարի և ոսկու պինդ թիթեղների միջև դիֆուզիան տարիների ընթացքում հասնում է ընդամենը փոքր հեռավորության։ Ուստի նույն պայմաններում ընդհանուր կարգն է՝ գազեր, հեղուկներ, պինդ մարմիններ։", "trigger_error_code": null, "allowed_parameter_keys": []}]'::jsonb);
insert into skill_outcomes select id,(select id from learning_outcomes limit 1) from skills;
